            trip = single([r for r in trips if r["Trip reference"] == claim["trip"] and r["Trip revision"] == claim["trip_revision"]], "claim trip revision")
            person = people[claim["employee"]]
            costs = tuple(line["cost_id"] for line in claim["lines"])
